style.css:
@-moz-document domain("roblox.com") {
/* Main background settings */
    body, 
    .container-main, 
    .content {
        background-image: url("https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHU4dG1ueGZqZnd4eHh4eHh4eHh4eHh4eHh4eHh4eHh4eHh4JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/4d980415-b812-4bcd-8930-d70dcbf9d196/giphy.gif") !important;
        background-attachment: fixed !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
    }

    /* Making site panels slightly transparent so you can actually see the GIF */
    .rbx-header, 
    .left-col-container, 
    .section-content, 
    .item-card-container, 
    .mcl-container {
        background-color: rgba(25, 25, 25, 0.8) !important;
        border: none !important;
    }

    /* Removing default dark/light backgrounds that might block the view */
    .dark-theme, .light-theme {
        background: transparent !important;
    }
}
